<script>
(function(){
  "use strict";

  /* ---------- THEME TOGGLE (in-memory, no storage APIs) ---------- */
  var root = document.documentElement;
  document.getElementById('themeToggle').addEventListener('click', function(){
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
  });

  /* ---------- MOBILE NAV ---------- */
  var navToggle = document.getElementById('navToggle');
  var navLinks = document.getElementById('navLinks');
  navToggle.addEventListener('click', function(){
    navToggle.classList.toggle('open');
    navLinks.classList.toggle('open');
  });
  navLinks.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', function(){
      navToggle.classList.remove('open');
      navLinks.classList.remove('open');
    });
  });

  /* ---------- STICKY NAVBAR + SCROLL TOP BUTTON + PROGRESS ---------- */
  var navbar = document.getElementById('navbar');
  var scrollTopBtn = document.getElementById('scrollTop');
  var scrollProgress = document.getElementById('scrollProgress');
  window.addEventListener('scroll', function(){
    var y = window.scrollY;
    navbar.classList.toggle('scrolled', y > 30);
    scrollTopBtn.classList.toggle('show', y > 500);
    var docHeight = document.documentElement.scrollHeight - window.innerHeight;
    var pct = docHeight > 0 ? (y / docHeight) * 100 : 0;
    scrollProgress.style.width = pct + '%';
  }, { passive: true });
  scrollTopBtn.addEventListener('click', function(){
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  /* ---------- HERO PHOTO TILT ---------- */
  var photoStage = document.querySelector('.photo-stage');
  var photoFrame = document.querySelector('.photo-frame');
  if(photoStage && photoFrame && window.matchMedia('(hover: hover)').matches && !window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    photoStage.addEventListener('mousemove', function(e){
      var rect = photoStage.getBoundingClientRect();
      var px = (e.clientX - rect.left) / rect.width - 0.5;
      var py = (e.clientY - rect.top) / rect.height - 0.5;
      photoFrame.style.transform = 'perspective(700px) rotateY(' + (px * 10) + 'deg) rotateX(' + (py * -10) + 'deg)';
    });
    photoStage.addEventListener('mouseleave', function(){
      photoFrame.style.transform = 'perspective(700px) rotateY(0deg) rotateX(0deg)';
    });
  }

  /* ---------- ACTIVE NAV LINK (scroll spy) ---------- */
  var sections = Array.from(document.querySelectorAll('section, header.hero'));
  var navItems = document.querySelectorAll('[data-nav]');
  var spy = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var id = entry.target.getAttribute('id');
        navItems.forEach(function(link){
          link.classList.toggle('active', link.getAttribute('href') === '#' + id);
        });
      }
    });
  }, { rootMargin: '-45% 0px -50% 0px', threshold: 0 });
  sections.forEach(function(s){ spy.observe(s); });

  /* ---------- REVEAL ON SCROLL ---------- */
  var revealEls = document.querySelectorAll('.reveal');
  var revealObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        entry.target.classList.add('in-view');
        obs.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });
  revealEls.forEach(function(el){ revealObserver.observe(el); });

  /* ---------- SKILL BAR FILL (animate once visible) ---------- */
  var barObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var fill = entry.target;
        fill.style.width = fill.getAttribute('data-level') + '%';
        obs.unobserve(fill);
      }
    });
  }, { threshold: 0.4 });
  document.querySelectorAll('.bar-fill').forEach(function(el){ barObserver.observe(el); });

  /* ---------- SCOPED TABS (skills / exercises) ---------- */
  function initTabs(containerSelector, panelSelector, onActivate){
    var container = document.querySelector(containerSelector);
    if(!container) return;
    var btns = container.querySelectorAll('.tab-btn');
    var panels = container.querySelectorAll(panelSelector);
    btns.forEach(function(btn){
      btn.addEventListener('click', function(){
        btns.forEach(function(b){ b.classList.remove('active'); });
        panels.forEach(function(p){ p.classList.remove('active'); });
        btn.classList.add('active');
        var target = container.querySelector(panelSelector + '[data-panel="' + btn.getAttribute('data-tab') + '"]');
        if(target){
          target.classList.add('active');
          if(onActivate) onActivate(target);
        }
      });
    });
  }

  initTabs('#skills', '.skills-panel', function(panel){
    panel.querySelectorAll('.bar-fill').forEach(function(fill){
      fill.style.width = fill.getAttribute('data-level') + '%';
    });
  });

  initTabs('#mini-projects', '.ex-panel');

  /* ---------- ROTATING ROLE LINE ---------- */
  var roles = ['Aspiring Full-Stack Web Developer', 'Digital Development Student', 'Front-End & Back-End Learner'];
  var roleEl = document.getElementById('roleWord');
  var roleIndex = 0;
  setInterval(function(){
    roleEl.classList.add('swap');
    setTimeout(function(){
      roleIndex = (roleIndex + 1) % roles.length;
      roleEl.textContent = roles[roleIndex];
      roleEl.classList.remove('swap');
    }, 350);
  }, 2800);

  /* ---------- TERMINAL TYPEWRITER ---------- */
  var terminalLines = [
    { html: '<span class="prompt">$</span> whoami' },
    { html: '<span class="out">ilyas_yekhlef</span>', pause: true },
    { html: '<span class="prompt">$</span> cat status.txt' },
    { html: '<span class="out">Digital Development Student</span>' },
    { html: '<span class="out">Aspiring Full-Stack Web Developer</span>' },
    { html: '<span class="out">Location: Tangier, Morocco</span>', pause: true },
    { html: '<span class="prompt">$</span> ./availability --check' },
    { html: '<span class="ok">&#10003; Open to internships &amp; junior roles</span>' }
  ];
  var terminalBody = document.getElementById('terminalBody');

  function typeLine(text, el, speed, cb){
    var i = 0;
    (function tick(){
      el.innerHTML = text.slice(0, i);
      i++;
      if(i <= text.length){
        setTimeout(tick, speed);
      } else if(cb){ cb(); }
    })();
  }

  function runTerminal(index){
    if(index >= terminalLines.length){
      var cursor = document.createElement('span');
      cursor.className = 'cursor';
      terminalBody.appendChild(cursor);
      return;
    }
    var line = terminalLines[index];
    var div = document.createElement('div');
    div.className = 'terminal-line';
    terminalBody.appendChild(div);
    typeLine(line.html, div, 18, function(){
      setTimeout(function(){ runTerminal(index + 1); }, line.pause ? 420 : 160);
    });
  }

  var terminalStarted = false;
  var terminalObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting && !terminalStarted){
        terminalStarted = true;
        runTerminal(0);
        obs.disconnect();
      }
    });
  }, { threshold: 0.3 });
  terminalObserver.observe(document.querySelector('.terminal'));

  /* ---------- CONTACT FORM (front-end only) ---------- */
  var form = document.getElementById('contactForm');
  var formMsg = document.getElementById('formMsg');
  var submitBtn = document.getElementById('submitBtn');
  var submitLabel = document.getElementById('submitLabel');

  form.addEventListener('submit', function(e){
    e.preventDefault();
    submitBtn.disabled = true;
    var dots = 0;
    submitLabel.textContent = 'sending';
    var typing = setInterval(function(){
      dots = (dots + 1) % 4;
      submitLabel.textContent = 'sending' + '.'.repeat(dots);
    }, 260);

    setTimeout(function(){
      clearInterval(typing);
      submitLabel.textContent = 'Send Message';
      submitBtn.disabled = false;
      formMsg.textContent = "Thanks for reaching out — I'll get back to you soon. (Connect this form to an email service or backend to receive real messages.)";
      formMsg.className = 'form-msg show ok';
      form.reset();
    }, 1100);
  });

})();
</script>
<div class="lb" id="lb" role="dialog" aria-modal="true" aria-label="Image viewer">
  <span class="lb-count" id="lbCount"></span>
  <button class="lb-btn lb-close" id="lbClose" aria-label="Close">&times;</button>
  <button class="lb-btn lb-prev" id="lbPrev" aria-label="Previous">&#8249;</button>
  <button class="lb-btn lb-next" id="lbNext" aria-label="Next">&#8250;</button>
  <div class="lb-stage" id="lbStage"><img id="lbImg" alt=""></div>
  <div class="lb-hint">Click image to zoom &middot; Esc to close &middot; &larr; &rarr; to navigate</div>
</div>
<script>
(function(){
  var lb=document.getElementById('lb'),img=document.getElementById('lbImg'),st=document.getElementById('lbStage'),cnt=document.getElementById('lbCount');
  var set=[],idx=0;
  function show(){var a=set[idx];img.src=a.querySelector('img').src;img.alt=a.querySelector('img').alt;st.classList.remove('zoom');st.scrollTop=0;
    cnt.textContent=set.length>1?(idx+1)+' / '+set.length:'';
    document.getElementById('lbPrev').style.display=document.getElementById('lbNext').style.display=set.length>1?'flex':'none';}
  function open(a){set=[].slice.call(a.parentNode.querySelectorAll('a'));idx=set.indexOf(a);show();lb.classList.add('open');document.body.style.overflow='hidden';}
  function close(){lb.classList.remove('open');document.body.style.overflow='';img.src='';}
  function step(d){idx=(idx+d+set.length)%set.length;show();}
  document.querySelectorAll('.mini-photos a').forEach(function(a){
    a.removeAttribute('target');a.addEventListener('click',function(e){e.preventDefault();open(a);});});
  img.addEventListener('click',function(){st.classList.toggle('zoom');});
  document.getElementById('lbClose').onclick=close;
  document.getElementById('lbPrev').onclick=function(){step(-1)};
  document.getElementById('lbNext').onclick=function(){step(1)};
  lb.addEventListener('click',function(e){if(e.target===lb||e.target===st)close();});
  document.addEventListener('keydown',function(e){if(!lb.classList.contains('open'))return;
    if(e.key==='Escape')close();else if(e.key==='ArrowLeft'&&set.length>1)step(-1);else if(e.key==='ArrowRight'&&set.length>1)step(1);});
})();
</script>
<canvas id="fireCanvas" aria-hidden="true"></canvas>
<script>
(function(){
  var cv=document.getElementById('fireCanvas');
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(cv&&!reduce){
    var c=cv.getContext('2d'),W,H,P=[],N=90,dpr=Math.min(window.devicePixelRatio||1,2);
    function size(){W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;c.setTransform(dpr,0,0,dpr,0,0);}
    size();addEventListener('resize',size);
    function mk(init){return{x:Math.random()*W,y:init?Math.random()*H:H+10,r:Math.random()*2.2+.6,vy:Math.random()*1.6+.6,
      sw:Math.random()*Math.PI*2,sp:Math.random()*.03+.01,life:Math.random()*.6+.4,h:Math.random()*40+190};}
    for(var i=0;i<N;i++)P.push(mk(true));
    var run=true;document.addEventListener('visibilitychange',function(){run=!document.hidden;if(run)loop();});
    function loop(){
      if(!run)return;c.clearRect(0,0,W,H);c.globalCompositeOperation='lighter';
      for(var i=0;i<P.length;i++){var p=P[i];p.y-=p.vy;p.sw+=p.sp;p.x+=Math.sin(p.sw)*.6;
        var a=Math.max(0,(p.y/H))*p.life;
        if(p.y<-10||a<=0){P[i]=mk(false);continue;}
        var g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*5);
        g.addColorStop(0,'hsla('+p.h+',100%,65%,'+a+')');g.addColorStop(.4,'hsla('+(p.h+10)+',100%,55%,'+a*.45+')');g.addColorStop(1,'hsla(225,100%,45%,0)');
        c.fillStyle=g;c.beginPath();c.arc(p.x,p.y,p.r*5,0,6.283);c.fill();}
      requestAnimationFrame(loop);}
    loop();
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest&&e.target.closest('.btn');if(!b)return;
    var r=b.getBoundingClientRect(),d=Math.max(r.width,r.height)*2,s=document.createElement('span');
    s.className='ripple';s.style.width=s.style.height=d+'px';s.style.left=(e.clientX-r.left-d/2)+'px';s.style.top=(e.clientY-r.top-d/2)+'px';
    b.appendChild(s);setTimeout(function(){s.remove()},700);});
})();
</script>
</body>
</html>
